import { useCallback, useMemo } from 'react';

import { useIntl } from 'react-intl';

import {
  Badge,
  Button,
  Icon,
  Page,
  SizableText,
  Skeleton,
  Stack,
  XStack,
  YStack,
} from '@onekeyhq/components';
import useAppNavigation from '@onekeyhq/kit/src/hooks/useAppNavigation';
import { useAppRoute } from '@onekeyhq/kit/src/hooks/useAppRoute';
import { useBorrowEModeStatus } from '@onekeyhq/kit/src/views/Borrow/hooks/useBorrowEModeStatus';
import { ETranslations } from '@onekeyhq/shared/src/locale';
import platformEnv from '@onekeyhq/shared/src/platformEnv';
import type {
  EModalStakingRoutes,
  IModalStakingParamList,
} from '@onekeyhq/shared/src/routes';

import { buildCategoryRowActivationProps } from '../BorrowEModeSwitch/categoryRowActivation';
import {
  type IEModeRow,
  buildEModeRowSubtitle,
  buildEModeRows,
} from '../BorrowEModeSwitch/emodeUtils';

function EModeCategoryRow({
  row,
  currentEModeId,
  isSelected,
  onPress,
}: {
  row: IEModeRow;
  currentEModeId: number;
  isSelected: boolean;
  onPress: (eModeId: number) => void;
}) {
  const intl = useIntl();

  const subtitle = buildEModeRowSubtitle({
    row,
    offText: intl.formatMessage({ id: ETranslations.defi_emode_off_desc }),
    formatMaxLtv: (ltv) =>
      intl.formatMessage({ id: ETranslations.defi_emode_max_ltv }, { ltv }),
    needsActionText: intl.formatMessage({
      id: ETranslations.defi_emode_need_action,
    }),
  });

  return (
    <XStack
      testID={`borrow-e-mode-category-row-${row.eModeId}`}
      ai="center"
      gap="$3"
      px="$5"
      py="$3"
      opacity={row.disabled ? 0.5 : 1}
      {...buildCategoryRowActivationProps({
        disabled: row.disabled,
        onActivate: () => onPress(row.eModeId),
        selected: isSelected,
        outlineOffset: -2,
      })}
    >
      <YStack flex={1} minWidth={0}>
        <XStack ai="center" gap="$2">
          <SizableText size="$bodyLgMedium" numberOfLines={1} flexShrink={1}>
            {row.displayLabel}
          </SizableText>
          {row.eModeId === currentEModeId ? (
            <Badge badgeType="info" badgeSize="sm">
              {intl.formatMessage({ id: ETranslations.global_current })}
            </Badge>
          ) : null}
        </XStack>
        <SizableText size="$bodySm" color="$textSubdued" numberOfLines={1}>
          {subtitle}
        </SizableText>
      </YStack>
      {isSelected ? (
        // The row already announces selection; hide the decorative checkmark.
        // Icon reads only name and style, so these have to sit on a view.
        <Stack
          flexShrink={0}
          accessibilityElementsHidden
          importantForAccessibility="no-hide-descendants"
          {...(platformEnv.isRuntimeBrowser
            ? { 'aria-hidden': true as const }
            : {})}
        >
          <Icon name="CheckLargeOutline" size="$5" color="$iconActive" />
        </Stack>
      ) : (
        <Stack flexShrink={0} w="$5" h="$5" />
      )}
    </XStack>
  );
}

export default function BorrowEModeCategorySelectModal() {
  const intl = useIntl();
  const navigation = useAppNavigation();
  const route = useAppRoute<
    IModalStakingParamList,
    EModalStakingRoutes.BorrowEModeCategorySelect
  >();
  const {
    networkId,
    provider,
    marketAddress,
    accountId,
    selectedEModeId,
    onSelect,
  } = route.params;

  // Same scope key as the switch page that pushed this screen, so this reads
  // straight out of the cache and then keeps following it.
  const { eModeStatus, isInitialLoading, isError, refresh } =
    useBorrowEModeStatus({
      networkId,
      provider,
      marketAddress,
      accountId,
      enabled: !!accountId,
    });

  const rows = useMemo(
    () =>
      buildEModeRows(
        eModeStatus,
        intl.formatMessage({ id: ETranslations.defi_emode_off }),
      ),
    [eModeStatus, intl],
  );

  // Without an explicit pick, keep the checkmark on the live current category.
  const currentEModeId = eModeStatus?.eModeId ?? 0;
  const resolvedSelection = selectedEModeId ?? currentEModeId;

  const observedCurrentEModeId = eModeStatus?.eModeId ?? null;
  const handleSelect = useCallback(
    (eModeId: number) => {
      onSelect(eModeId, observedCurrentEModeId);
      navigation.pop();
    },
    [navigation, observedCurrentEModeId, onSelect],
  );

  const title = intl.formatMessage({
    id: ETranslations.defi_emode_select_category,
  });

  // The cache normally seeds this screen before it paints, so these states
  // only appear when the request comes back empty or the cache is cold.
  const showError = isError && !eModeStatus;
  const showSkeleton = !showError && isInitialLoading;

  return (
    <Page scrollEnabled>
      <Page.Header title={title} />
      <Page.Body>
        {showError ? (
          <YStack gap="$4" py="$8" px="$5" ai="center">
            <SizableText size="$bodyLg" color="$textSubdued">
              {intl.formatMessage({ id: ETranslations.defi_emode_load_error })}
            </SizableText>
            <Button
              size="medium"
              variant="secondary"
              testID="borrow-e-mode-category-retry"
              onPress={() => void refresh()}
            >
              {intl.formatMessage({ id: ETranslations.global_retry })}
            </Button>
          </YStack>
        ) : null}
        {showSkeleton ? (
          <YStack py="$2" testID="borrow-e-mode-category-skeleton">
            {[0, 1, 2].map((key) => (
              <XStack key={key} ai="center" gap="$3" px="$5" py="$3">
                <YStack flex={1} gap="$2">
                  <Skeleton w={120} h="$5" borderRadius="$2" />
                  <Skeleton w={180} h="$4" borderRadius="$2" />
                </YStack>
              </XStack>
            ))}
          </YStack>
        ) : null}
        {showError || showSkeleton ? null : (
          <YStack
            py="$2"
            accessibilityRole="radiogroup"
            accessibilityLabel={title}
            {...(platformEnv.isRuntimeBrowser
              ? { role: 'radiogroup' as const, 'aria-label': title }
              : {})}
          >
            {rows.map((row) => (
              <EModeCategoryRow
                key={row.eModeId}
                row={row}
                currentEModeId={currentEModeId}
                isSelected={row.eModeId === resolvedSelection}
                onPress={handleSelect}
              />
            ))}
          </YStack>
        )}
      </Page.Body>
    </Page>
  );
}
